import ctypes
import os
import hashlib
import hmac
import struct
import tempfile
from typing import Optional, Tuple

# Secure shared memory buffer manager for IPC
# Uses ctypes for high-performance direct memory operations

class SecureBufferManager:
    """Manages a shared memory buffer with integrity verification.

    Security features:
    - HMAC integrity checks on all buffer operations
    - Bounds checking before every read/write
    - Size validation with overflow protection
    - Access control via capability tokens
    """

    BUFFER_SIZE = 4096  # Fixed buffer size
    HEADER_SIZE = 64    # Reserved for metadata
    MAX_WRITE_SIZE = BUFFER_SIZE - HEADER_SIZE  # 4032 bytes max payload
    HMAC_KEY = os.urandom(32)

    # ctypes structure matching C layout
    class BufferHeader(ctypes.Structure):
        _fields_ = [
            ("magic", ctypes.c_uint32),
            ("version", ctypes.c_uint16),
            ("flags", ctypes.c_uint16),
            ("data_offset", ctypes.c_uint32),
            ("data_length", ctypes.c_uint32),
            ("checksum", ctypes.c_uint32 * 8),
            ("reserved", ctypes.c_uint8 * 16),
        ]

    def __init__(self):
        self._buffer = (ctypes.c_uint8 * self.BUFFER_SIZE)()
        self._header = ctypes.cast(self._buffer, ctypes.POINTER(self.BufferHeader)).contents
        self._header.magic = 0xDEADBEEF
        self._header.version = 1
        self._header.data_offset = self.HEADER_SIZE
        self._header.data_length = 0
        self._access_tokens = {}
        self._operation_log = []

    def generate_access_token(self, user_id: str, permissions: str) -> str:
        """Generate a capability token for buffer access."""
        token_data = f"{user_id}:{permissions}:{os.urandom(16).hex()}"
        token_hmac = hmac.new(self.HMAC_KEY, token_data.encode(), hashlib.sha256).hexdigest()
        token = f"{token_data}:{token_hmac}"
        self._access_tokens[token] = {"user": user_id, "perms": permissions}
        return token

    def _verify_token(self, token: str, required_perm: str) -> bool:
        """Verify capability token and check permissions."""
        if not token or token not in self._access_tokens:
            return False
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return False
        token_data, provided_hmac = parts
        expected_hmac = hmac.new(self.HMAC_KEY, token_data.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected_hmac, provided_hmac):
            return False
        token_info = self._access_tokens[token]
        return required_perm in token_info["perms"]

    def _compute_integrity(self, data: bytes) -> bytes:
        """Compute HMAC integrity tag for data."""
        return hmac.new(self.HMAC_KEY, data, hashlib.sha256).digest()

    def _validate_bounds(self, offset: int, length: int) -> bool:
        """Validate that offset + length doesn't exceed buffer bounds.

        All arithmetic performed in Python's arbitrary-precision integers
        to prevent any truncation or overflow issues.
        """
        # Ensure non-negative values
        if offset < 0 or length < 0:
            return False

        # Calculate end position using Python native integers
        # (no truncation possible - Python ints are arbitrary precision)
        end = offset + length

        # Bounds check: end must not exceed buffer size
        if end > self.BUFFER_SIZE:
            return False

        # Additional: offset itself must be within buffer
        if offset >= self.BUFFER_SIZE:
            return False

        return True

    def _log_operation(self, op: str, offset: int, length: int, user: str):
        """Audit log for all buffer operations."""
        self._operation_log.append({
            "op": op,
            "offset": offset,
            "length": length,
            "user": user,
        })

    def write_data(self, token: str, data: bytes, offset: int = 0) -> Tuple[bool, str]:
        """Write data to buffer at specified offset within data region.

        Args:
            token: Access capability token
            data: Bytes to write
            offset: Offset within the data region (added to HEADER_SIZE)

        Returns:
            Tuple of (success, message)
        """
        # Step 1: Verify access token
        if not self._verify_token(token, 'w'):
            return (False, "Access denied: invalid token or insufficient permissions")

        user = self._access_tokens[token]["user"]

        # Step 2: Basic input validation
        if not isinstance(data, bytes):
            return (False, "Data must be bytes")
        if not isinstance(offset, int) or offset < 0:
            return (False, "Offset must be non-negative integer")

        # Step 3: Length validation
        length = len(data)
        if length == 0:
            return (False, "Cannot write empty data")
        if length > self.MAX_WRITE_SIZE:
            return (False, f"Data exceeds maximum write size of {self.MAX_WRITE_SIZE}")

        # Step 4: Calculate absolute buffer position
        absolute_offset = self.HEADER_SIZE + offset

        # Step 5: Bounds validation using Python native arithmetic
        if not self._validate_bounds(absolute_offset, length):
            return (False, "Write would exceed buffer bounds")

        # Step 6: Perform the write
        for i in range(length):
            self._buffer[absolute_offset + i] = data[i]

        # Step 7: Update header metadata
        total_data_end = offset + length
        if total_data_end > self._header.data_length:
            self._header.data_length = total_data_end

        # Step 8: Compute and store integrity
        integrity = self._compute_integrity(data)
        for i in range(min(8, len(integrity) // 4)):
            self._header.checksum[i] = struct.unpack_from('<I', integrity, i * 4)[0]

        # Step 9: Audit log
        self._log_operation("write", absolute_offset, length, user)

        return (True, f"Successfully wrote {length} bytes at offset {offset}")

    def read_data(self, token: str, offset: int = 0, length: Optional[int] = None) -> Tuple[Optional[bytes], str]:
        """Read data from buffer."""
        if not self._verify_token(token, 'r'):
            return (None, "Access denied")

        user = self._access_tokens[token]["user"]

        if length is None:
            length = self._header.data_length - offset
            if length <= 0:
                return (b"", "No data at offset")

        absolute_offset = self.HEADER_SIZE + offset

        if not self._validate_bounds(absolute_offset, length):
            return (None, "Read would exceed buffer bounds")

        result = bytes(self._buffer[absolute_offset:absolute_offset + length])
        self._log_operation("read", absolute_offset, length, user)
        return (result, f"Read {length} bytes")

    def get_audit_log(self, token: str) -> Tuple[Optional[list], str]:
        """Retrieve operation audit log."""
        if not self._verify_token(token, 'a'):
            return (None, "Access denied")
        return (list(self._operation_log), "OK")
